SET client_encoding = 'UTF8';
BEGIN;
UPDATE articulos SET metadata = '{"areas": ["corporalidad", "sociabilidad", "creatividad"], "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "cantidad": "04 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa"], "objetivos": ["Conocer las capacidades corporales", "Desarrollar la motricidad", "Estimular la coordinación", "Crear un ambiente de distensión"], "materiales": ["Ninguno"], "variaciones": "<b>Espejo en Descompresión:</b> Realizar los movimientos en cámara lenta extrema con música instrumental suave.<br><b>Espejo de Máquinas Scouts:</b> Cada pareja imita el movimiento de un engranaje o herramienta de construcción de campamento.<br><b>Espejo de Seisena:</b> Toda la seisena imita las gesticulaciones de Akela o del seisenero durante una danza scout.", "recomendaciones": "Generar un clima de confianza donde nadie se sienta juzgado. Adaptar la exigencia física a las capacidades del grupo.", "justificacion_areas": "El Espejo Colectivo Scout potencia la corporalidad al afinar el esquema corporal, el equilibrio tónico y la fluidez del movimiento corporal. Desarrolla la sociabilidad al requerir una mirada atenta, empática y de absoluta confianza con la pareja de juego. Fortalece la creatividad al estimular la innovación de gestos y secuencias corporales.", "objetivos_educativos": [{"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "unidad": "Manada", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "como_se_cumple": "Participando con entusiasmo en la imitación física de posturas para ganar flexibilidad y soltura corporal."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "unidad": "Manada", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "como_se_cumple": "Afinando el control psicomotriz de brazos, piernas y manos al replicar la figura de la pareja espejo."}, {"id": "273f60b8-7953-4416-97c3-e8c83615364f", "area": "Corporalidad", "unidad": "Compañía", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Ejercitando la postura física y el tono muscular en la dinámica de reflejo síncrono."}, {"id": "91473f71-9345-4bcf-bfc7-dea709d12361", "area": "Corporalidad", "unidad": "Compañía", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Respetando la expresión e imagen corporal de la pareja durante la imitación de movimientos síncronos."}, {"id": "5c9843d1-39fd-4298-870c-5e46f29ffbf6", "area": "Corporalidad", "unidad": "Tropa", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Desarrollando el control del eje corporal y la precisión kinésica en dinámicas de grupo."}, {"id": "fb56310a-a9cf-46e3-9c34-c4643f6b9035", "area": "Corporalidad", "unidad": "Tropa", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Fomentando el respeto por la diversidad corporal y el lenguaje físico en la Tropa."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "unidad": "Manada", "como_se_cumple": "Respetando con honestidad el turno de guía y el ritmo de mi pareja de espejo."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "unidad": "Manada", "como_se_cumple": "Acatando las reglas de imitación síncrona sin distraer a las demás parejas."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Compañía", "como_se_cumple": "Favoreciendo el juego limpio, el respeto visual y la contención afectiva."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Compañía", "como_se_cumple": "Promoviendo un ambiente de integración, escucha atenta y lealtad de patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Tropa", "como_se_cumple": "Cumpliendo con lealtad las consignas de reflejo síncrono corporal."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Tropa", "como_se_cumple": "Afianzando la cohesión y hermandad comunitaria en toda la Tropa."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "texto": "Me gusta participar en juegos de observación.", "unidad": "Manada", "como_se_cumple": "Observando con detalle las posturas de los compañeros para replicarlas con precisión."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "unidad": "Manada", "como_se_cumple": "Deduciendo con agilidad los cambios de movimiento en la dinámica espejo."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "texto": "Doy mi opinión sobre las cosas que me pasan.", "unidad": "Compañía", "como_se_cumple": "Expresando reflexiones sobre la experiencia de imitar e interpretar al otro."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "unidad": "Compañía", "como_se_cumple": "Analizando la perspectiva corporal del reflejo desde el ángulo del compañero."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "texto": "Doy mi opinión sobre las cosas que me pasan.", "unidad": "Tropa", "como_se_cumple": "Aportando dinamismo e improvisación postural en cada ronda de juego."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "unidad": "Tropa", "como_se_cumple": "Sintetizando señas físicas sutiles para sincronizar el movimiento de patrulla."}]}'::jsonb WHERE slug = 'el-espejo-colectivo-scout';
DELETE FROM articulo_objetivos_educativos WHERE articulo_id = (SELECT id FROM articulos WHERE slug = 'el-espejo-colectivo-scout');
COMMIT;